import 'package:flutter/material.dart';

import '../theme/theme.dart';

/// The LifeMeter mark: a cobalt tile with a white horizon bar in the lower
/// third and a fluoro-pink half-disc sun rising on it. It's still morning.
/// Mirrors `assets/images/logo.svg` (generated by the scratchpad logo.py).
class LogoMark extends StatelessWidget {
  const LogoMark({super.key, this.size = 40, this.tile = cobalt});

  final double size;
  final Color tile;

  static const cobalt = Color(0xFF2340F5);
  static const pink = Color(0xFFFF48B0);

  @override
  Widget build(BuildContext context) {
    return Semantics(
      label: 'LifeMeter',
      image: true,
      child: SizedBox.square(
        dimension: size,
        child: CustomPaint(painter: LogoPainter(tile)),
      ),
    );
  }
}

/// Geometry shared with logo.py (fractions of the tile side).
class LogoPainter extends CustomPainter {
  const LogoPainter(this.tile, {this.drawTile = true});

  final Color tile;
  final bool drawTile;

  static const barY = 0.62;
  static const barH = 0.075;
  static const barW = 0.64;
  static const sunR = 0.22;

  @override
  void paint(Canvas canvas, Size size) {
    final s = size.shortestSide;
    if (drawTile) {
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          Offset.zero & Size.square(s),
          Radius.circular(s * 0.24),
        ),
        Paint()..color = tile,
      );
    }
    final cx = s / 2;
    final barTop = s * barY;
    // The sun: a half-disc sitting on the bar.
    canvas.save();
    canvas.clipRect(Rect.fromLTRB(0, 0, s, barTop));
    canvas.drawCircle(
      Offset(cx, barTop),
      s * sunR,
      Paint()..color = LogoMark.pink,
    );
    canvas.restore();
    canvas.drawRRect(
      RRect.fromRectAndRadius(
        Rect.fromLTWH(cx - s * barW / 2, barTop, s * barW, s * barH),
        Radius.circular(s * barH / 2),
      ),
      Paint()..color = Colors.white,
    );
  }

  @override
  bool shouldRepaint(LogoPainter old) => old.tile != tile;
}

/// Mark plus "LifeMeter" in Schibsted 700.
class Wordmark extends StatelessWidget {
  const Wordmark({super.key, this.size = 20, this.color, this.mark = true});

  final double size;
  final Color? color;
  final bool mark;

  @override
  Widget build(BuildContext context) {
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        if (mark) ...[
          LogoMark(size: size * 1.35),
          SizedBox(width: size * 0.45),
        ],
        Text(
          'LifeMeter',
          style: context.type.title.copyWith(
            fontSize: size,
            letterSpacing: -0.4,
            color: color ?? context.lm.ink,
          ),
        ),
      ],
    );
  }
}
